CREATE FUNCTION pg_temp.reject_publication_audit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Injected audit failure'; END $$;
DO $$
DECLARE source uuid:=pg_temp.publication_source(); old_draft uuid; v uuid; fresh uuid; report jsonb; saved jsonb; snapshot jsonb; req uuid:=gen_random_uuid(); actor uuid:=auth.uid(); name text; pid uuid;
BEGIN
 old_draft:=public.cms_create_draft(source,'Old publication draft',gen_random_uuid());
 v:=public.cms_create_draft(source,'Publication draft',gen_random_uuid());
 SELECT jsonb_agg(to_jsonb(f) ORDER BY scenario_id,fact_role) INTO snapshot FROM public.scenario_fact_copy f WHERE version_id=v;
 INSERT INTO cms_private.choice_order SELECT v,choice_id,137 FROM public.choices WHERE version_id=v;
 report:=public.cms_publication_preflight(v); ASSERT (report->>'can_publish')::boolean;
 BEGIN UPDATE public.content_versions SET status='published',published_at=clock_timestamp() WHERE version_id=v; RAISE EXCEPTION 'Expected guard denial'; EXCEPTION WHEN raise_exception THEN ASSERT SQLERRM LIKE 'CMS editions cannot%'; END;
 BEGIN UPDATE public.content_versions SET cms_managed=false WHERE version_id=v; RAISE EXCEPTION 'Expected flag denial'; EXCEPTION WHEN raise_exception THEN ASSERT SQLERRM LIKE 'CMS editions cannot%'; END;
 BEGIN PERFORM public.cms_publish_draft(v,1,req,report->>'validator',report->'heads'); RAISE EXCEPTION 'Expected stale'; EXCEPTION WHEN serialization_failure THEN NULL; END;
 CREATE TRIGGER local_publication_fault BEFORE INSERT ON cms_private.publications FOR EACH ROW EXECUTE FUNCTION pg_temp.reject_publication_audit();
 BEGIN PERFORM public.cms_publish_draft(v,0,req,report->>'validator',report->'heads'); RAISE EXCEPTION 'Expected injected failure'; EXCEPTION WHEN raise_exception THEN ASSERT SQLERRM='Injected audit failure'; END;
 ASSERT (SELECT status='draft' AND published_at IS NULL FROM public.content_versions WHERE version_id=v);
 ASSERT (SELECT revision=0 FROM cms_private.workspaces WHERE version_id=v);
 ASSERT NOT EXISTS(SELECT 1 FROM cms_private.publication_permits);
 ASSERT NOT EXISTS(SELECT 1 FROM cms_private.publications WHERE version_id=v);
 DROP TRIGGER local_publication_fault ON cms_private.publications;
 saved:=public.cms_publish_draft(v,0,req,report->>'validator',report->'heads');
 ASSERT saved=public.cms_publish_draft(v,0,req,report->>'validator',report->'heads');
 ASSERT (SELECT pub.result=saved AND pub.actor=auth.uid() AND pub.saved_revision=0 FROM cms_private.publications pub WHERE pub.version_id=v);
 ASSERT NOT EXISTS(SELECT 1 FROM cms_private.publication_permits);
 ASSERT cms_private.publication_heads()=jsonb_build_object('individual',v,'group',v);
 ASSERT snapshot=(SELECT jsonb_agg(to_jsonb(f) ORDER BY scenario_id,fact_role) FROM public.scenario_fact_copy f WHERE version_id=v);
 ASSERT NOT EXISTS(SELECT 1 FROM jsonb_array_elements(public.cms_list_drafts()) x WHERE x->>'version_id'=v::text);
 ASSERT public.cms_read_draft(v)->'publication'=saved;
 BEGIN UPDATE cms_private.publications SET validator='changed' WHERE version_id=v; RAISE EXCEPTION 'Expected immutable audit'; EXCEPTION WHEN raise_exception THEN ASSERT SQLERRM='Publication audit records are immutable'; END;
 BEGIN UPDATE public.personas SET description='Forbidden' WHERE version_id=v; RAISE EXCEPTION 'Expected immutable content'; EXCEPTION WHEN raise_exception THEN ASSERT SQLERRM='Editable CMS draft required'; END;
 BEGIN PERFORM public.cms_delete_draft(v,1); RAISE EXCEPTION 'Expected published delete denial'; EXCEPTION WHEN raise_exception THEN ASSERT SQLERRM='Unpublished CMS draft required'; END;
 BEGIN PERFORM public.cms_publish_draft(v,0,req,'changed',report->'heads'); RAISE EXCEPTION 'Expected retry mismatch'; EXCEPTION WHEN raise_exception THEN ASSERT SQLERRM LIKE 'Publication request reused%'; END;
 ASSERT EXISTS(SELECT 1 FROM public.content_versions WHERE version_id=source AND status='published');
 report:=public.cms_publication_preflight(old_draft);
 ASSERT NOT (report->>'can_publish')::boolean;
 ASSERT EXISTS(SELECT 1 FROM jsonb_array_elements(report->'findings') x WHERE x->>'code'='PUB-ORDER');
 UPDATE public.scenarios SET title='Only in old draft' WHERE version_id=old_draft AND title='Ordinary 01';
 req:=gen_random_uuid();
 fresh:=public.cms_recover_draft(old_draft,0,v,'Fresh from latest',req);
 ASSERT fresh=public.cms_recover_draft(old_draft,0,v,'Fresh from latest',req);
 ASSERT (SELECT source_version=v AND revision=0 FROM cms_private.workspaces WHERE version_id=fresh);
 ASSERT EXISTS(SELECT 1 FROM public.scenarios WHERE version_id=old_draft AND title='Only in old draft');
 ASSERT NOT EXISTS(SELECT 1 FROM public.scenarios WHERE version_id=fresh AND title='Only in old draft');
 ASSERT (SELECT count(*)=31 FROM public.scenarios WHERE version_id=fresh);
 ASSERT (SELECT count(*)=62 FROM public.scenario_fact_copy WHERE version_id=fresh AND NOT verified);
 ASSERT (SELECT count(*)=31 FROM cms_private.choice_order o JOIN cms_private.lineage l ON l.draft_id=o.choice_id AND l.version_id=fresh AND l.table_name='choices' WHERE o.version_id=fresh AND o.position=137);
 ASSERT NOT EXISTS(SELECT 1 FROM cms_private.choice_order o JOIN public.choices c USING(choice_id) WHERE o.version_id=fresh AND c.version_id<>fresh);
 ASSERT (public.cms_publication_preflight(fresh)->>'can_publish')::boolean;
 UPDATE public.cac_staff SET active=false WHERE user_id=actor;
 BEGIN PERFORM public.cms_publish_draft(v,0,req,'cms-publication-v1','{}'); RAISE EXCEPTION 'Expected staff denial'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 UPDATE public.cac_staff SET active=true WHERE user_id=actor;
 ASSERT NOT has_function_privilege('anon','public.cms_publish_draft(uuid,integer,uuid,text,jsonb)','EXECUTE');
 ASSERT NOT has_table_privilege('authenticated','cms_private.publication_permits','INSERT');
 RAISE NOTICE 'Stage 3 atomic publication/rollback/receipt/retry/immutability/reopening/source-copy/recovery/order/authorization passed';
END $$;
ROLLBACK;
